('text', 'home.cart.body', 0, $j${"value": "Specialty coffee, handcrafted chai, and ceremonial matcha — served fresh, on-site, wherever Houston gathers. Weddings, office events, showers, celebrations, and community gatherings."}$j$::jsonb),
('text', 'home.community.quote', 0, $j${"value": "“The best conversations happen over great coffee.”"}$j$::jsonb),
('text', 'home.community.title', 0, $j${"value": "Where every visit tells a story"}$j$::jsonb),
('text', 'home.gallery.title', 0, $j${"value": "Moments at RAAHA"}$j$::jsonb),
('text', 'home.events.title', 0, $j${"value": "Events & experiences"}$j$::jsonb),
('text', 'home.events.intro', 0, $j${"value": "From thoughtful gatherings to creative collaborations, RAAHA brings people together through experiences that inspire conversation, creativity, learning, and community."}$j$::jsonb),
('text', 'home.team.title', 0, $j${"value": "Passionate about people & hospitality?"}$j$::jsonb),
('text', 'home.team.body', 0, $j${"value": "At RAAHA, we believe great hospitality is about more than serving coffee—it’s about making people feel seen, welcomed, and at home. If you enjoy creating meaningful experiences, working with intention, and being part of a community-driven team, we’d love to meet you."}$j$::jsonb),
('text', 'home.newsletter.title', 0, $j${"value": "Stay connected"}$j$::jsonb),
('text', 'home.newsletter.body', 0, $j${"value": "Be the first to hear about seasonal drinks, community events, workshops, and thoughtful moments happening at RAAHA."}$j$::jsonb),
('text', 'home.idea.body', 0, $j${"value": "A cup of coffee or chai can start a conversation, spark an idea, reconnect old friends, or introduce strangers who become part of each other’s stories. We believe these everyday moments matter.\n\nThat’s why RAAHA is designed as more than a place to eat or drink. It’s a welcoming café where hospitality comes first, people feel at ease, and genuine connection has room to grow.\n\nBecause when we care for one another and the communities around us, we create places worth returning to."}$j$::jsonb),
('text', 'home.space.body', 0, $j${"value": "At RAAHA, every corner is created with intention. Whether you’re catching up with friends, working quietly, reading a book, or sharing a cup of chai, the space is designed to help you feel comfortable, connected, and at ease."}$j$::jsonb),
('text', 'home.community.body', 0, $j${"value": "At RAAHA, we celebrate meaningful conversations, creativity, hospitality, friendship, and the simple joy of slowing down together.\n\nThis is a place where old friends reconnect, new friendships begin, ideas are shared, and every visit feels welcoming."}$j$::jsonb),
