('text', 'cart.hero.title', 0, $j${"value": "Bring RAAHA to Your Gathering"}$j$::jsonb),
('text', 'cart.hero.lede', 0, $j${"value": "Specialty coffee, handcrafted chai, and ceremonial matcha — served fresh, on-site, wherever Houston gathers."}$j$::jsonb),
('text', 'cart.intro.title', 0, $j${"value": "Coffee, Chai & Matcha for Your Event"}$j$::jsonb),
('text', 'cart.intro.body', 0, $j${"value": "The RAAHA Coffee Cart brings the same care, craft, and hospitality that define RAAHA Soul House directly to your gathering. Every cup is made to order — specialty espresso, handcrafted chai, and ceremonial matcha — served by a team that treats your guests the way we treat ours.\n\nWhether it's an intimate celebration or a large community gathering, the Coffee Cart is built to bring people together over something warm, well made, and shared."}$j$::jsonb),
('text', 'cart.menu.intro', 0, $j${"value": "A curated selection from the RAAHA menu, built for event service. Full menus are customized to your guest count and event type."}$j$::jsonb),
('text', 'cart.area.intro', 0, $j${"value": "The RAAHA Coffee Cart currently serves gatherings across the greater Houston area, including:"}$j$::jsonb),
('text', 'cart.area.note', 0, $j${"value": "Outside these neighborhoods? Reach out below — we evaluate requests across the greater Houston metro on a case-by-case basis."}$j$::jsonb),
