('faq', null, 10, $j${"question": "How far in advance should I book?", "answer": "We recommend booking at least 3–4 weeks ahead of your event date. Peak season and weekend dates fill faster, so earlier requests get first choice of timing."}$j$::jsonb),
('faq', null, 20, $j${"question": "What is the minimum guest count for booking?", "answer": "The Coffee Cart is built for gatherings of 25 guests and up. Smaller or larger events are welcome — share your guest count in the booking form and we'll confirm fit and pricing."}$j$::jsonb),
('faq', null, 30, $j${"question": "Do you need power or water access at the venue?", "answer": "The cart can run on standard power access; for venues without power on-site, let us know in your booking details and we'll confirm what's needed ahead of time."}$j$::jsonb),
('faq', null, 40, $j${"question": "Can the menu be customized for my event?", "answer": "Yes. The sample menu above reflects our core event offerings — we can tailor drink selection, quantities, and add-ons to your guest count, budget, and occasion."}$j$::jsonb),
('faq', null, 50, $j${"question": "How long does the cart stay at an event?", "answer": "Standard service windows are 2–3 hours. Extended service is available — note your preferred duration in the booking form and we'll confirm pricing."}$j$::jsonb),
('faq', null, 60, $j${"question": "How does payment and deposit work?", "answer": "A deposit secures your date, with the remaining balance due ahead of the event. Full details are confirmed once we review your booking request."}$j$::jsonb)
